extends Resource
class_name TetrominoData

@export var cells: Array[Vector2i]
@export var atlas_coords: Vector2i

extends Node2D

@export var shapes: Array[TetrominoData]
@export var tile_map: TileMapLayer
@export var timer: Timer

var current_cells: Array[Vector2i]
var current_pos: Vector2i
var atlas_pos: Vector2i

func _ready():
	spawn_piece()

func spawn_piece():
	var data = shapes.pick_random()
	if not data:
		return
	current_cells = data.cells
	atlas_pos = data.atlas_coords
	current_pos = Vector2i(3, 0)
	if not is_valid_move(current_cells, current_pos):
		game_over()
		return
	draw_piece()

func is_valid_move(cells: Array[Vector2i], pos: Vector2i) -> bool:
	for cell in cells:
		var target = cell + pos
		if target.x < 0 or target.x >= 10 or target.y >= 20:
			return false
		if tile_map.get_cell_source_id(target) != -1:
			return false
	return true

func draw_piece():
	for cell in current_cells:
		tile_map.set_cell(current_pos + cell, 0, atlas_pos)

func game_over():
	print('ИГРА ОКОНЧЕНА')
	get_tree().paused = true

func move_piece(direction: Vector2i):
	clear_piece()
	if is_valid_move(current_cells, current_pos + direction):
		current_pos += direction
		draw_piece()
	else:
		draw_piece()
		if direction == Vector2i(0, 1):
			lock_piece()

func lock_piece():
	check_lines()
	spawn_piece()

func clear_piece():
	for cell in current_cells:
		tile_map.set_cell(current_pos + cell, -1)

func check_lines():
	for y in range(19, -1, -1):
		var is_full = true
		for x in range(10):
			if tile_map.get_cell_source_id(Vector2i(x, y)) == -1:
				is_full = false
				break
		if is_full:
			delete_line(y)
			check_lines()
			break

func delete_line(y: int):
	for row in range(y, 0, -1):
		for x in range(10):
			var above_atlas = tile_map.get_cell_atlas_coords(Vector2i(x, row - 1))
			var source_id = tile_map.get_cell_source_id(Vector2i(x, row - 1))
			tile_map.set_cell(Vector2i(x, row), source_id, above_atlas)

func _unhandled_input(event):
	if event.is_action_pressed('left'): move_piece(Vector2i(-1, 0))
	if event.is_action_pressed('right'): move_piece(Vector2i(1, 0))
	if event.is_action_pressed('soft_drop'): move_piece(Vector2i(0, 1))

func rotate_piece():
	clear_piece()

	var new_cells: Array[Vector2i] = []

	for cell in current_cells:
		var rotated_x = -cell.y
		var rotated_y = cell.x
		new_cells.append(Vector2i(rotated_x, rotated_y))

	if is_valid_move(new_cells, current_pos):
		current_cells = new_cells

	draw_piece()

func hard_drop():
	clear_piece()
	while is_valid_move(current_cells, current_pos + Vector2i(0, 1)):
		current_pos += Vector2i(0, 1)

	draw_piece()
	lock_piece()

