@rpc('any_peer', 'call_remote')
func receive_garbage(count: int):
	# Сдвигаем всё поле игрока вверх на 'count' линий
	# И снизу добавляем линии с одной случайной дыркой
	for i in range(count):
		grid.add_garbage_row()

@rpc('any_peer', 'call_local')
func player_lost(id: int):
	print('Игрок ', id, ' выбыл из битвы!')
	check_winner()
